/**
 * Memastikan tabel Master_Pegawai_POA, Master_Standar_Pelatihan, dan TX_TU_Pelatihan_Pegawai terisi data awal.
 * Idempoten: Hanya menyemaikan jika sheet masih kosong (atau force === true).
 *
 * @param {boolean} [force=false]
 * @returns {{success:boolean, pegawaiCount:number, standarCount:number}}
 */
function ensurePegawaiPelatihanSeeded(force) {
  var tuId = ensureTuSpreadsheet();
  var ss = SpreadsheetApp.openById(tuId);

  var pSheet = ss.getSheetByName(SHEET_TU.PEGAWAI_MASTER) || _autoCreateTuSheet(ss, SHEET_TU.PEGAWAI_MASTER);
  var sSheet = ss.getSheetByName(SHEET_TU.STANDAR_PELATIHAN) || _autoCreateTuSheet(ss, SHEET_TU.STANDAR_PELATIHAN);
  var tSheet = ss.getSheetByName(SHEET_TU.PELATIHAN_PEGAWAI) || _autoCreateTuSheet(ss, SHEET_TU.PELATIHAN_PEGAWAI);

  var pLast = pSheet.getLastRow();
  var sLast = sSheet.getLastRow();

  var seededPegawai = 0;
  var seededStandar = 0;

  // 1. Seed Master Standar Pelatihan (termasuk Juru Masak)
  if (sLast <= 1 || force) {
    if (force && sLast > 1) {
      sSheet.getRange(2, 1, sLast - 1, sSheet.getLastColumn()).clearContent();
    }
    var sRows = [];
    for (var grp in STANDAR_PELATIHAN_RESMI) {
      if (STANDAR_PELATIHAN_RESMI.hasOwnProperty(grp)) {
        var items = STANDAR_PELATIHAN_RESMI[grp];
        for (var i = 0; i < items.length; i++) {
          var itm = items[i];
          sRows.push([
            itm.kode,
            grp,
            itm.tingkat || 'ALL',
            itm.kat || 'TEKNIS',
            itm.nama,
            itm.wajib ? true : false,
            i + 1
          ]);
        }
      }
    }
    if (sRows.length > 0) {
      sSheet.getRange(2, 1, sRows.length, sRows[0].length).setValues(sRows);
      seededStandar = sRows.length;
    }
  } else {
    // Self-heal kurikulum Juru Masak pada database yang sudah ter-seed sebelumnya
    try {
      var existingCodes = {};
      var curS = sSheet.getRange(2, 1, sLast - 1, 1).getValues();
      for (var sc = 0; sc < curS.length; sc++) {
        existingCodes[String(curS[sc][0] || '').trim()] = true;
      }
      var jmkItems = STANDAR_PELATIHAN_RESMI['Juru Masak'] || [];
      var missingJmk = [];
      for (var jm = 0; jm < jmkItems.length; jm++) {
        if (!existingCodes[jmkItems[jm].kode]) {
          missingJmk.push([
            jmkItems[jm].kode, 'Juru Masak', jmkItems[jm].tingkat || 'ALL',
            jmkItems[jm].kat || 'TEKNIS', jmkItems[jm].nama, !!jmkItems[jm].wajib, jm + 1
          ]);
        }
      }
      if (missingJmk.length > 0) {
        sSheet.getRange(sLast + 1, 1, missingJmk.length, 7).setValues(missingJmk);
      }
    } catch (eJmk) {}
  }

  if (typeof ensurePegawaiMasterColumns === 'function') {
    ensurePegawaiMasterColumns();
  }

  // 2. Seed Master Pegawai POA & Awak Kapal (528 Personel sinkron SKP)
  if (pLast <= 1 || force) {
    if (force && pLast > 1) {
      pSheet.getRange(2, 1, pLast - 1, pSheet.getLastColumn()).clearContent();
    }
    var nowStr = new Date().toISOString();
    var pRows = [];
    for (var p = 0; p < SEED_PEGAWAI_POA_AWAK.length; p++) {
      var peg = SEED_PEGAWAI_POA_AWAK[p];
      var rawNipSeed = String(peg.nip || '').trim();
      var isP3kNip = /^\d{12}21\d{4}$/.test(rawNipSeed);
      var sPeg = peg.statusKepegawaian || (isP3kNip ? 'P3K' : ((peg.unit === 'Dit. POA' || peg.lingkup === 'DIT_POA') ? 'PNS' : (rawNipSeed && rawNipSeed !== '-' ? 'PNS' : 'NON_ASN')));
      if (sPeg === 'PPPK_FUNGSIONAL' || sPeg === 'PPPK_PELAKSANA') sPeg = 'P3K';
      if (sPeg === 'PPPK_PARUH_WAKTU') sPeg = 'P3K_PARUH_WAKTU';
      var cleanNama = typeof sanitizeNamaPersonel === 'function' ? sanitizeNamaPersonel(peg.nama) : String(peg.nama || '').toUpperCase().trim();
      var stPenempatan = peg.statusPenempatan || ((String(peg.unit || '').toLowerCase().indexOf('pangkalan') !== -1 || String(peg.unit || '').toLowerCase().indexOf('stasiun') !== -1) ? 'DIPERBANTUKAN_UPT' : 'PUSAT_POA');
      pRows.push([
        peg.pegawaiId,
        (sPeg === 'PJLP' || sPeg === 'MAGANG' || rawNipSeed === '-') ? '' : rawNipSeed,
        cleanNama,
        peg.unit,
        peg.lingkup,
        peg.kelompokJabatan,
        peg.jabatanLengkap,
        peg.tingkatKelas,
        peg.rumpun,
        sPeg,
        peg.statusAktif || 'AKTIF',
        peg.subJenisSDM || '',
        peg.nomorIdentitas || '',
        peg.institusiAsal || '',
        peg.tanggalMulai || '',
        peg.tanggalSelesai || '',
        peg.mentorPembimbing || '',
        peg.catatanTambahan || '',
        peg.dokumenSkUrl || '',
        peg.dokumenSkEvidenceId || '',
        stPenempatan,
        peg.kapalPenempatan || '',
        peg.ukuranBaju || '',
        peg.ukuranSepatu || '',
        'MANUAL_TU',
        'LENGKAP',
        '',
        nowStr,
        'SYSTEM_SEED'
      ]);
    }
    if (pRows.length > 0) {
      pSheet.getRange(2, 1, pRows.length, pRows[0].length).setValues(pRows);
      seededPegawai = pRows.length;
    }
  }

  if (typeof applyFormalSheetFormatting === 'function') {
    applyFormalSheetFormatting(sSheet, SHEET_TU.STANDAR_PELATIHAN);
    applyFormalSheetFormatting(pSheet, SHEET_TU.PEGAWAI_MASTER);
    applyFormalSheetFormatting(tSheet, SHEET_TU.PELATIHAN_PEGAWAI);
  }

  return {
    success: true,
    pegawaiCount: seededPegawai || (pSheet.getLastRow() - 1),
    standarCount: seededStandar || (sSheet.getLastRow() - 1)
  };
}
